export const BODY: string = "\n<p>ویب پر ہر تصویر دو شکلوں میں سے ایک میں موجود ہوتی ہے: نام اور URL والی فائل کے طور پر، یا کوڈ میں ایمبیڈ شدہ Base64 اسٹرنگ کے طور پر۔ دونوں میں ایک ہی پکسل ہوتے ہیں، مگر ان کا برتاؤ بہت مختلف ہوتا ہے۔</p>\n<p>غلط شکل چننا کارکردگی کو نقصان پہنچاتا ہے، بینڈوڈتھ ضائع کرتا ہے، یا سادہ اپ ڈیٹ کو تکلیف دہ کام بنا دیتا ہے۔ درست شکل چننا زیادہ تر فرق جاننے کا معاملہ ہے۔</p>\n<p>اس مضمون میں Base64 اسٹرنگ اور تصویری فائلوں کا آمنے سامنے موازنہ کیا گیا ہے: سائز، رفتار، کیشنگ، ایڈیٹنگ، اور وہ استعمال جہاں ہر ایک واضح جیتتا ہے۔</p>\n<h2 id=\"two-ways-to-store-an-image\">ایک ہی تصویر محفوظ کرنے کے دو طریقے</h2>\n<p>تصویری فائل نام، فارمیٹ اور مقام والا بائنری ڈیٹا ہوتی ہے۔ براؤزر اسے درخواست سے لاتا ہے، کیش کرتا ہے، اور جب بھی صفحہ اس کا حوالہ دے تو رینڈر کرتا ہے۔</p>\n<p>Base64 اسٹرنگ وہی بائنری ڈیٹا ہے جو متن کے طور پر دوبارہ لکھا گیا ہے۔ یہ HTML، CSS، JSON یا ڈیٹا بیس کے اندر رہتی ہے، اور براؤزر اسے بغیر کسی درخواست کے موقع پر ڈی کوڈ کرتا ہے۔</p>\n<p>دونوں شکلوں میں پکسل ایک جیسے ہوتے ہیں۔ PNG فائل اور اس کی Base64 اسٹرنگ ایک ہی بائٹ، ایک ہی ابعاد اور ایک ہی تصویر میں ڈی کوڈ ہوتی ہیں۔</p>\n<p>باقی سب مختلف ہوتا ہے: سائز، رفتار، کیشنگ، ایڈیٹنگ اور ٹولنگ۔ یہ فرق ہی اس موازنے کا موضوع ہیں۔</p>\n<h2 id=\"size-comparison\">سائز: 33 فیصد کا فرق</h2>\n<p>Base64 اسٹرنگ اس فائل سے تقریباً 33 فیصد بڑی ہوتی ہے جسے وہ انکوڈ کرتی ہے۔ 90 KB تصویر 120 KB اسٹرنگ بن جاتی ہے، اور 1 MB تصویر 1.4 MB اسٹرنگ بن جاتی ہے۔</p>\n<p>یہ فرق انکوڈنگ کی مستقل خصوصیت ہے۔ چار متن حروف تین بائٹ ڈیٹا لے جاتے ہیں، اس لیے اسٹرنگ کو ہمیشہ فائل سے ایک تہائی زیادہ حروف چاہیے ہوتے ہیں۔</p>\n<p>چھوٹی تصاویر کے لیے یہ فرق معمولی ہوتا ہے۔ 3 KB آئیکن 4 KB اسٹرنگ بن جاتا ہے، اور کوئی ایک کلو بائٹ نہیں ناپتا۔ بڑی تصاویر کے لیے یہ فرق فیصلے پر حاوی ہو جاتا ہے۔</p>\n<p>فائل سائز اسٹوریج کے لیے بھی اہمیت رکھتا ہے۔ Base64 تصاویر سے بھرا ڈیٹا بیس فائلوں کے طور پر محفوظ شدہ انہی تصاویر سے ایک تہائی بڑا ہوتا ہے، اور یہ قیمت ہر بیک اپ میں دہرائی جاتی ہے۔</p>\n<h2 id=\"performance-loading\">کارکردگی: لوڈنگ رفتار</h2>\n<p>لنک شدہ تصویری فائل درخواست لیتی ہے مگر بتدریج رینڈر ہوتی ہے۔ براؤزر پہلے متن دکھاتا ہے اور تصویر آنے پر بھر دیتا ہے، اس لیے صفحہ تیز لگتا ہے چاہے تصویر ابھی آ رہی ہو۔</p>\n<p>ایمبیڈ شدہ Base64 تصویر کوئی درخواست نہیں لیتی مگر رینڈرنگ بلاک کرتی ہے۔ براؤزر کو کچھ بھی دکھانے سے پہلے پورا HTML دستاویز ڈاؤن لوڈ کرنا پڑتا ہے، اسٹرنگ سمیت۔</p>\n<p>ایک چھوٹے آئیکن والے صفحے کے لیے ایمبیڈنگ تیز ہوتی ہے۔ بچائی گئی درخواست اضافی بائٹ سے زیادہ قیمتی ہوتی ہے، اور آئیکن پہلی پینٹ کے ساتھ ظاہر ہوتا ہے۔</p>\n<p>بہت سی یا بڑی تصاویر والے صفحے کے لیے لنکنگ تیز ہوتی ہے۔ متن فوراً رینڈر ہوتا ہے، تصاویر اندر آتی ہیں، اور براؤزر قاری کی دیکھنے والی چیز کو ترجیح دے سکتا ہے۔</p>\n<h2 id=\"caching\">کیشنگ: فیصلہ کن فرق</h2>\n<p>کیشنگ وہ جگہ ہے جہاں تصویری فائلیں فیصلہ کن طور پر جیتتی ہیں۔ لنک شدہ فائل ایک بار ڈاؤن لوڈ ہوتی ہے اور ہر اس صفحے پر دوبارہ استعمال ہوتی ہے جو اس کا حوالہ دے، جب تک کیش ہیڈر اجازت دیں۔</p>\n<p>Base64 اسٹرنگ ہر اس صفحے کے ساتھ دوبارہ ڈاؤن لوڈ ہوتی ہے جس میں وہ ہو۔ پچاس صفحات پر ایمبیڈ شدہ لوگو پچاس ڈاؤن لوڈ لیتی ہے، جبکہ وہی لوگو لنک شدہ ایک ڈاؤن لوڈ لیتی ہے۔</p>\n<p>مشترکہ تصاویر کے لیے فائلوں کو ترجیح دینے کی یہ سب سے بڑی وجہ ہے۔ 33 فیصد اوور ہیڈ ایک بار کی قیمت ہے، مگر کیشنگ کا نقصان ہر صفحہ دیکھنے پر دہرایا جاتا ہے۔</p>\n<p>ایک صفحے والے دستاویزات، ای میل اور آف لائن فائلوں کے لیے کیشنگ لاگو نہیں ہوتی، اور دلیل غائب ہو جاتی ہے۔ اسی لیے ایمبیڈنگ بالکل انہی صورتوں میں معیاری عمل ہے۔</p>\n<h2 id=\"portability\">پورٹیبلٹی: تصاویر کو ادھر ادھر لے جانا</h2>\n<p>Base64 اسٹرنگ متن کے اندر سفر کرتی ہیں، جو انہیں ایسے طریقوں سے پورٹیبل بناتا ہے جو فائلیں نہیں ہوتیں۔ اسٹرنگ کو چیٹ میسج میں پیسٹ کیا جا سکتا ہے، ڈیٹا بیس قطار میں محفوظ کیا جا سکتا ہے، یا JSON پے لوڈ میں ایمبیڈ کیا جا سکتا ہے۔</p>\n<p>تصویری فائلوں کو مقام چاہیے ہوتا ہے: URL، فولڈر یا اٹیچمنٹ۔ فائل کو منتقل کرنے کا مطلب ہے حوالہ بھی منتقل کرنا، اور ٹوٹا ہوا حوالہ ٹوٹی تصویر بناتا ہے۔</p>\n<p>API اسٹرنگ کے لیے سب سے واضح صورت ہیں۔ JSON بائنری ڈیٹا نہیں لے جا سکتا، اس لیے JSON پے لوڈ کے اندر سفر کرنے والی کوئی بھی تصویر Base64 ہونی چاہیے، اور فائل پر مبنی کوئی متبادل نہیں۔</p>\n<p>ویب سائٹس کے لیے عملی طور پر فائلیں زیادہ پورٹیبل ہوتی ہیں۔ فائل کا کسی بھی صفحے، کسی بھی اسٹائل شیٹ اور کسی بھی ای میل سے حوالہ دیا جا سکتا ہے، جبکہ اسٹرنگ کو ہر جگہ کاپی کرنا پڑتا ہے۔</p>\n<h2 id=\"editing-and-versioning\">ایڈیٹنگ اور ورژن کنٹرول</h2>\n<p>لنک شدہ تصویر اپ ڈیٹ کرنا فائل کی تبدیلی ہے۔ فائل بدلیں، نام وہی رکھیں، اور ہر صفحہ جو اس کا حوالہ دے فوراً نیا ورژن دکھاتا ہے۔</p>\n<p>ایمبیڈ شدہ تصویر اپ ڈیٹ کرنے کا مطلب ہے اسٹرنگ ڈھونڈنا، متن کی دیوار بدلنا، اور امید کرنا کہ آپ نے درست والی بدلی۔ کوڈ بدلتا ہے حالانکہ منطق نہیں بدلی۔</p>\n<p>ورژن کنٹرول اسٹرنگ کے ساتھ متاثر ہوتا ہے۔ تصویر میں ایک لائن کی تبدیلی ہزار لائنوں کا فرق بن جاتی ہے، جو حقیقی کوڈ تبدیلیوں کو ڈبو دیتی ہے اور جائزوں کو تکلیف دہ بنا دیتی ہے۔</p>\n<p>فائلیں صاف ورژن ہوتی ہیں۔ بدلی ہوئی تصویر بدلی ہوئی بائنری فائل ہوتی ہے، فرق ایک لائن ہوتا ہے، اور تاریخ بالکل دکھاتی ہے کہ تصویر کب بدلی اور کیا بدلا۔</p>\n<h2 id=\"search-and-accessibility\">سرچ، رسائی اور شیئرنگ</h2>\n<p>سرچ انجن لنک شدہ تصویری فائلوں کو انڈیکس کرتے ہیں اور انہیں تصویری سرچ میں دکھاتے ہیں۔ ایمبیڈ شدہ Base64 تصویر اس نظام کے لیے بڑی حد تک نظر نہیں آتی، اس لیے وہ کوئی تصویری سرچ ٹریفک نہیں لاتی۔</p>\n<p>اسکرین ریڈر اور رسائی کے اوزار دونوں شکلوں کے ساتھ کام کرتے ہیں، مگر صرف تب جب مارک اپ درست ہو۔ تصویری ایلیمنٹ کو alt وصف چاہیے ہوتا ہے چاہے اس کا ماخذ فائل ہو یا اسٹرنگ۔</p>\n<p>قارئین لنک شدہ تصویر پر دائیں کلک کر کے اسے محفوظ، شیئر یا نئے ٹیب میں کھول سکتے ہیں۔ ایمبیڈ شدہ تصویر زیادہ تر براؤزرز میں وہی مینو دیتی ہے، مگر محفوظ شدہ فائل کا نام اکثر گندا ہوتا ہے۔</p>\n<p>سوشل شیئرنگ پیش نظارہ بھی فائلوں کو ترجیح دیتے ہیں۔ ایمبیڈ شدہ تصاویر پر انحصار کرنے والا صفحہ شیئر ہونے پر کوئی پیش نظارہ تھمب نیل نہیں دکھا سکتا، کیونکہ شیئرنگ کرالر اسٹرنگ نہیں پڑھ سکتا۔</p>\n<h2 id=\"api-and-data-transfer\">API اور ڈیٹا منتقلی</h2>\n<p>JSON قبول کرنے والی API تصاویر کو Base64 اسٹرنگ کے طور پر توقع رکھتی ہیں، کیونکہ JSON میں کوئی بائنری قسم نہیں۔ اسٹرنگ فیلڈ میں سفر کرتی ہے، سرور اسے ڈی کوڈ کرتا ہے، اور فائل دوبارہ بن جاتی ہے۔</p>\n<p>ملٹی پارٹ اپ لوڈ فائل پر مبنی متبادل ہیں، اور بڑی تصاویر کے لیے زیادہ مؤثر ہیں۔ ملٹی پارٹ درخواست بائنری کو سیدھا بھیجتی ہے، بغیر 33 فیصد اوور ہیڈ کے۔</p>\n<p>JSON ورک فلو میں چھوٹی تصاویر، جیسے اوتار، دستخط اور تھمب نیل، کے لیے Base64 چنیں۔ بڑی تصاویر کے لیے ملٹی پارٹ اپ لوڈ چنیں، جہاں اوور ہیڈ نقصان دہ ہوتا۔</p>\n<p>ڈیٹا بیس بھی اسی منطق پر چلتے ہیں۔ متن کے طور پر محفوظ شدہ چھوٹی تصاویر آسان ہوتی ہیں، جبکہ بڑی تصاویر آبجیکٹ اسٹوریج میں رہتی ہیں اور ڈیٹا بیس میں ان کا حوالہ ہوتا ہے۔</p>\n<h2 id=\"email-use-cases\">ای میل: اسٹرنگ چھوٹی جیتتی ہے، فائل بڑی جیتتی ہے</h2>\n<p>ای میل واحد پیغامات ہوتے ہیں، اس لیے ایمبیڈ شدہ تصویر متن کے ساتھ سفر کرتی ہے اور قاری آف لائن ہو تب بھی دکھائی دیتی ہے۔ یہ لنک شدہ تصویر پر حقیقی فائدہ ہے۔</p>\n<p>چھوٹی تصاویر ای میل میں اچھی ایمبیڈ ہوتی ہیں: 10 KB سے نیچے لوگو، آئیکن اور چھوٹے بینر۔ وہ پیغام کو اسی لمحے پہچاننے کے قابل بناتی ہیں جب وہ کھلتا ہے۔</p>\n<p>بڑی تصاویر لنک ہی رہنی چاہیے یا چھوڑ دینی چاہیے۔ بھاری ایمبیڈ شدہ تصویر پیغام کو فون پر آہستہ کھولتی ہے، اور کچھ میل سرور سائز کی حد سے اوپر کے پیغامات مسترد کر دیتے ہیں۔</p>\n<p>ان کلائنٹس میں آزمائیں جو آپ کے سامعین استعمال کرتے ہیں۔ کچھ ان لائن Base64 تصاویر کو مکمل بلاک کر دیتے ہیں، جو ان قارئین کے لیے پوری ایمبیڈنگ کوشش کو بے فائدہ بنا دیتا ہے۔</p>\n<h2 id=\"security-considerations\">سیکیورٹی کے غور</h2>\n<p>Base64 اسٹرنگ اپنے مواد کو عام معائنے سے چھپاتی ہے۔ کوڈ کو اسکین کرنے والا جائزہ لینے والا اسٹرنگ ڈی کوڈ کیے بغیر نہیں دیکھ سکتا کہ تصویر کیا دکھاتی ہے، جو سیکیورٹی جائزوں کو مشکل بنا دیتا ہے۔</p>\n<p>کنٹینٹ سیکیورٹی پالیسی ہیڈر Data URL کو بلاک کر سکتے ہیں۔ سخت پالیسی جو تصاویر کو صرف آپ کے اپنے ڈومین سے اجازت دیتی ہے وہ ایمبیڈ شدہ تصویر کو مسترد کر دے گی جب تک data: کی واضح اجازت نہ ہو۔</p>\n<p>تصویری فائلوں کا آڈٹ آسان ہوتا ہے۔ فائل کو اسکین، ہیش اور معروف مواد کی فہرست سے چیک کیا جا سکتا ہے، جبکہ اسٹرنگ کو کسی بھی جانچ سے پہلے ڈی کوڈ کرنا پڑتا ہے۔</p>\n<p>غیر معتبر ماخذ سے اسٹرنگ کو ڈی کوڈ کر کے نتیجہ اندھا نہ پیش کریں۔ ڈی کوڈ شدہ بائٹ کو محفوظ یا دکھانے سے پہلے حقیقی تصویر کے طور پر تصدیق کریں۔</p>\n<h2 id=\"when-files-win\">جب تصویری فائلیں واضح جیتتی ہیں</h2>\n<p>تصویری فائلیں تصاویر، سائٹ بھر کے لوگو، اور 50 KB سے اوپر کی ہر چیز کے لیے جیتتی ہیں۔ کیشنگ کی بچت اور رینڈرنگ رفتار درخواست کی بچت سے کہیں زیادہ جیتتی ہے۔</p>\n<p>فائلیں بدلنے والی تصاویر کے لیے جیتتی ہیں۔ فائل کی تبدیلی ہر حوالے کو ایک ساتھ اپ ڈیٹ کرتی ہے، جبکہ اسٹرنگ اپ ڈیٹ کا مطلب ہے ہر وہ فائل ایڈٹ کرنا جس میں ایمبیڈ شدہ کاپی ہو۔</p>\n<p>فائلیں ڈھونڈی جانے والی تصاویر کے لیے جیتتی ہیں۔ سرچ انجن، سوشل پیش نظارہ اور تصویری سرچ سب لنک شدہ فائلوں کے ساتھ ایمبیڈ شدہ اسٹرنگ سے بہتر کام کرتے ہیں۔</p>\n<p>فائلیں ٹیموں کے لیے جیتتی ہیں۔ ڈیزائنر کوڈ چھوئے بغیر فائل بدل سکتا ہے، ڈویلپر تبدیلی کو صاف جائزہ لے سکتا ہے، اور ورژن تاریخ پڑھنے کے قابل رہتی ہے۔</p>\n<h2 id=\"when-strings-win\">جب Base64 اسٹرنگ واضح جیتتی ہیں</h2>\n<p>اسٹرنگ ان واحد فائل دستاویزات کے لیے جیتتی ہیں جو آف لائن کام کرنی چاہیے۔ HTML رپورٹ، محفوظ شدہ ویب صفحہ، یا ای میل بیرونی فائلیں نہیں لا سکتی، اس لیے ایمبیڈنگ ہی واحد راستہ ہے۔</p>\n<p>اسٹرنگ 2 KB سے نیچے چھوٹے آئیکن کے لیے جیتتی ہیں۔ اوور ہیڈ ایک کلو بائٹ سے کم ہوتا ہے، بچائی گئی درخواست حقیقی ہوتی ہے، اور اتنی چھوٹی تصویر کے لیے کیشنگ کا نقصان معمولی ہوتا ہے۔</p>\n<p>اسٹرنگ JSON پے لوڈ اور ڈیٹا بیس فیلڈ کے لیے جیتتی ہیں۔ متن پر مبنی سسٹم بائنری ڈیٹا نہیں لے جا سکتے، اس لیے Base64 ان کے ذریعے تصویر منتقل کرنے کا معیاری طریقہ ہے۔</p>\n<p>اسٹرنگ بغیر گھر والی تیار شدہ تصاویر کے لیے جیتتی ہیں۔ اسکرپٹ سے موقع پر بنائی گئی تصویر فوراً ایمبیڈ ہو سکتی ہے، بغیر پہلے اسے سرور پر محفوظ کیے اور URL حاصل کیے۔</p>\n<h2 id=\"hybrid-approach\">ہائبرڈ طریقہ</h2>\n<p>زیادہ تر حقیقی پروجیکٹ دونوں شکلیں استعمال کرتے ہیں۔ چھوٹے آئیکن ایمبیڈ ہوتے ہیں، تصاویر لنک ہوتی ہیں، اور API پے لوڈ Base64 لے جاتے ہیں جبکہ ویب سائٹ فائلیں پیش کرتی ہے۔</p>\n<p>ہائبرڈ اصول سادہ ہے: جو چھوٹا اور ضروری ہو اسے ایمبیڈ کریں، جو بڑا یا مشترکہ ہو اسے لنک کریں، اور اسٹرنگ وہاں استعمال کریں جہاں نقل و حمل متن پر مبنی ہو۔</p>\n<p>انتخاب کو فی تصویر نہیں بلکہ فی تصویر قسم دستاویز کریں۔ 5 KB سے نیچے آئیکن ایمبیڈ ہوتے ہیں، باقی سب لنک ہوتا ہے جیسا اصول پیروی اور آڈٹ کرنا آسان ہوتا ہے۔</p>\n<p>جب پروجیکٹ بدلے تو اصول پر دوبارہ غور کریں۔ جو لینڈنگ پیج پوری سائٹ بن جائے اس کے ایمبیڈ شدہ لوگو کو واپس لنک شدہ فائل میں بدلنا پڑ سکتا ہے۔</p>\n<h2 id=\"migration-checklist\">دونوں شکلوں کے درمیان منتقلی</h2>\n<p>اسٹرنگ سے فائلوں کی طرف جانا سیدھا ہے۔ اسٹرنگ کو <a href=\"/ur/base64-ko-tasveer-mein-convert-karein/\">Base64 to image decoder</a> سے ڈی کوڈ کریں، فائل محفوظ کریں، اپ لوڈ کریں، اور اسٹرنگ کو URL سے بدلیں۔</p>\n<p>فائلوں سے اسٹرنگ کی طرف جانا اتنا ہی آسان ہے۔ فائل کو <a href=\"/ur/tasveer-ko-base64-mein-convert-karein/\">image to Base64 encoder</a> سے انکوڈ کریں، آؤٹ پٹ کاپی کریں، اور اسے وہاں پیسٹ کریں جہاں URL تھا۔</p>\n<p>منتقلی ایک وقت میں ایک تصویر قسم سے کریں، اور پہلے اور بعد میں ناپیں۔ جو منتقلی سائٹ کو سست کرے وہ واپس لینے کے قابل منتقلی ہے۔</p>\n<p>منتقلی کے دوران اصل رکھیں۔ ڈی کوڈ شدہ فائل اور اس کی ماخذ اسٹرنگ دونوں موجود ہونی چاہیے جب تک نیا ورژن آزما کر تصدیق نہ ہو جائے۔</p>\n<h2 id=\"cost-bandwidth-storage\">قیمت: بینڈوڈتھ اور اسٹوریج</h2>\n<p>بینڈوڈتھ Base64 انتخاب کی سب سے ٹھوس قیمت ہے۔ 1 MB ایمبیڈ شدہ تصاویر والا صفحہ تقریباً 1.33 MB تصویری ڈیٹا منتقل کرتا ہے، جبکہ وہی تصاویر لنک شدہ صرف 1 MB منتقل کرتی ہیں۔</p>\n<p>میٹرڈ موبائل کنکشن پر اضافی تہائی قاری کے لیے حقیقی پیسہ ہے۔ جو سائٹ بہت زیادہ ایمبیڈ کرتی ہے وہ اپنے موبائل ناظرین کو لنک کرنے والی سائٹ سے نمایاں زیادہ ڈیٹا خرچ کرا سکتی ہے۔</p>\n<p>اسٹوریج بھی اسی تناسب پر چلتا ہے۔ جو ڈیٹا بیس 10 GB تصاویر کو Base64 کے طور پر رکھتا ہے وہ 13.3 GB متن رکھتا ہے، اور ہر بیک اپ، نقل اور منتقلی یہ اضافی وزن اٹھاتی ہے۔</p>\n<p>تصاویر کے لیے آبجیکٹ اسٹوریج ڈیٹا بیس اسٹوریج سے سستا ہوتا ہے، جو بڑی تصاویر کے فائلوں میں رہنے کی ایک اور وجہ ہے۔ ڈیٹا بیس میں حوالہ چند درجن حروف لیتا ہے۔</p>\n<p>کمپیوٹ سب سے چھوٹی قیمت ہے۔ انکوڈنگ اور ڈی کوڈنگ تیز عمل ہیں، اور CPU وقت نیٹ ورک اور اسٹوریج قیمت کے سامنے معمولی ہوتا ہے، اس لیے کارکردگی کا فرق وہاں نہیں ہوتا۔</p>\n<p>جب آپ ایمبیڈنگ کی قیمت کا اندازہ لگائیں تو اسے صفحہ دیکھنے کی تعداد سے ضرب دیں۔ ایک دورے پر معمولی لگنے والا 100 KB اوور ہیڈ لاکھوں دوروں پر 10 GB اضافی منتقلی بن جاتا ہے۔</p>\n<h2 id=\"quick-reference\">فوری حوالہ: اسٹرنگ یا فائلیں</h2>\n<p>تصاویر، مشترکہ لوگو، بڑی تصاویر، اور ہر اس چیز کے لیے تصویری فائلیں استعمال کریں جسے کیشنگ، سرچ انڈیکسنگ یا بار بار اپ ڈیٹ چاہیے ہو۔</p>\n<p>چھوٹے آئیکن، واحد فائل دستاویزات، ای میل، اور JSON پے لوڈ کے لیے Base64 اسٹرنگ استعمال کریں، جہاں متن پر مبنی نقل و حمل فائلوں کو ناممکن یا ناقابلِ عمل بنا دیتی ہے۔</p>\n<p>دونوں شکلیں ایک ہی پکسل لے جاتی ہیں، اس لیے انتخاب تصویر کے بارے میں نہیں بلکہ تصویر کے ارد گرد نظام کے بارے میں ہے۔ وہ شکل چنیں جو نقل و حمل، کیشنگ اور دیکھ بھال سے میل کھائے۔</p>\n<p>ٹولز کے لیے <a href=\"/ur/tasveer-ko-base64-mein-convert-karein/\">image to Base64 encoder</a> اور <a href=\"/ur/base64-ko-tasveer-mein-convert-karein/\">Base64 to image decoder</a> استعمال کریں۔ ایمبیڈنگ کے فیصلے کے ڈھانچے کے لیے <a href=\"/ur/blog/base64-tasveer-kab-embed-karein/\">Base64 Images: When to Embed and When Not To</a> پڑھیں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"کیا Base64 تصویر عام تصویری فائل سے آہستہ لوڈ ہوتی ہے؟","answer":"یہ سائز اور سیاق پر منحصر ہے۔ چھوٹا ایمبیڈ شدہ آئیکن تیزی سے لوڈ ہوتا ہے کیونکہ یہ درخواست بچاتا ہے، جبکہ بڑی ایمبیڈ شدہ تصویر آہستہ لوڈ ہوتی ہے کیونکہ یہ رینڈرنگ بلاک کرتی ہے اور کیش نہیں ہو سکتی۔ زیادہ تر تصاویر کے لیے فائلیں تیز ہوتی ہیں۔"},{"question":"کیا میں Base64 اسٹرنگ کو واپس فائل میں بدل کر عام طور پر ہوسٹ کر سکتا ہوں؟","answer":"ہاں۔ اسٹرنگ کو Base64 to image ڈی کوڈر میں پیسٹ کریں، اسے اصل، PNG، JPG یا WebP کے طور پر ڈاؤن لوڈ کریں، اور فائل کو اپنے سرور پر اپ لوڈ کریں۔ ایمبیڈ شدہ اسٹرنگ کو فائل URL سے بدلیں، اور تصویر عام لنک شدہ فائل بن جاتی ہے۔"},{"question":"کیا Base64 تصاویر تمام براؤزرز میں کام کرتی ہیں؟","answer":"Data URL تمام جدید براؤزرز میں کام کرتے ہیں، جن میں Chrome، Safari، Firefox اور Edge شامل ہیں۔ بہت پرانے براؤزرز میں Data URL پر سائز کی حدیں تھیں، مگر موجودہ ورژن میں وہ ختم ہو گئی ہیں۔ ای میل کلائنٹ استثنا ہیں، وہاں سپورٹ غیر مستقل رہتی ہے۔"},{"question":"کئی تصاویر ایمبیڈ کرنے کے بعد میرا ویب صفحہ اتنا سست کیوں ہے؟","answer":"کیونکہ ایمبیڈ شدہ اسٹرنگ نے HTML دستاویز کو بہت بڑا بنا دیا، اور براؤزر کو رینڈر کرنے سے پہلے یہ سب ڈاؤن لوڈ کرنا پڑتا ہے۔ ہر تصویر فائل سے 33 فیصد زیادہ بائٹ بھی لیتی ہے۔ بڑی تصاویر کو لنک شدہ فائلوں میں منتقل کریں۔"},{"question":"کیا Base64 اسٹرنگ ڈیٹا بیس میں صارف اوتار محفوظ کرنے کے لیے محفوظ ہیں؟","answer":"وہ آسان ہیں مگر فطری طور پر محفوظ نہیں۔ Base64 انکوڈنگ ہے، خفیہ کاری نہیں، اس لیے ڈیٹا بیس تک رسائی والا کوئی بھی اسٹرنگ کو تصویر میں ڈی کوڈ کر سکتا ہے۔ اوتار کو آبجیکٹ اسٹوریج میں فائلوں کے طور پر محفوظ کریں اور ڈیٹا بیس میں حوالہ رکھیں۔"},{"question":"API میں Base64 کے بجائے ملٹی پارٹ اپ لوڈ کب استعمال کروں؟","answer":"بڑی تصاویر کے لیے ملٹی پارٹ اپ لوڈ استعمال کریں، کیونکہ یہ بائنری کو سیدھا بھیجتا ہے بغیر 33 فیصد اوور ہیڈ کے۔ Base64 تب استعمال کریں جب API صرف JSON قبول کرے، جب تصویر چھوٹی ہو، یا جب کلائنٹ ملٹی پارٹ بھیج نہ سکے۔"}];
